mapper.select:
select uc.id, uc.coupon_id as couponId, c.name as couponName, c.type, c.value, c.min_amount as minAmount, uc.status, uc.receive_time as receiveTime, uc.expire_time as expireTime, mp.shop_name as merchantName from user_coupon uc left join coupon c on uc.coupon_id = c.id left join merchant_profile mp on c.merchant_id = mp.user_id where uc.user_id = #{userId}
and uc.status = #{status}
order by uc.receive_time desc
